// Role card as data: reviewable, diffable, testable (plain JS)
const triageSpecialist = {
  role: "Returns Triage Specialist",
  goal: "Route every ticket to exactly one of [billing, shipping, returns] with confidence; unknowns to human.",
  backstory: "Knows the 30-day/receipt/final-sale policy; lateness is shipping, never damage.",
  tools: ["read_ticket"],                 // reads only: no writes, no refunds
  mustNot: ["issue refunds", "contact customers"],  // jurisdiction edge, explicit
};
// mustNot is the senior field: authority stated by exclusion, not implication.

// Overlap audit: pairwise mandate comparison (plain JS pattern)
function auditRoles(roles) {
  const findings = [];
  const verbs = (r) => new Set((r.goal + " " + (r.mustNot || []).join(" ")).toLowerCase().match(/[a-z]+/g));
  for (let i = 0; i < roles.length; i++)
    for (let j = i + 1; j < roles.length; j++) {
      const shared = [...verbs(roles[i])].filter((w) => verbs(roles[j]).has(w) && w.length > 4);
      if (shared.length) findings.push(`${roles[i].role} × ${roles[j].role}: shared terms [${shared.join(", ")}] — justify or split`);
    }
  return findings;
}
// Heuristic tripwire (shared vocabulary), human verdict: justify or split.

