  { role: 'Triage', goal: 'route every ticket quickly', mustNot: ['issue refunds'] },
  { role: 'Quality', goal: 'ensure every ticket quality quickly', mustNot: [] },
  { role: 'Finance', goal: 'issue approved refunds accurately', mustNot: ['contact customers'] },
];
const findings = auditRoles(roster);
console.log('pairs flagged: ' + findings.length);
for (const f of findings) console.log(f);

